/bin/bash -lc "python - <<'PY'
import json, os, requests
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f:
    key=f.read().strip()
hid='bbd44e69cb8906b504048fc466cb1540'
fastq='f9cad7b01a472135c6849dc539693d01'
headers={'x-api-key':key}
submissions=[
 ('fastq_to_fasta', 'toolshed.g2.bx.psu.edu/repos/devteam/fastqtofasta/fastq_to_fasta_python/1.2+galaxy0', {'input_file': {'src':'hda','id':fastq}}),
 ('trinity_single', 'toolshed.g2.bx.psu.edu/repos/iuc/trinity/trinity/2.15.1+galaxy1', {
   'pool': {'pool_mode':'Yes', 'inputs': {'paired_or_single':'single', 'input': {'src':'hda','id':fastq}, 'strand': {'is_strand_specific':'false'}}},
   'no_normalize_reads': True,
   'additional_params': {'guided': {'is_guided':'no'}}
 })
]
for name, tool_id, inputs in submissions:
    payload={'history_id':hid,'tool_id':tool_id,'inputs':inputs,'input_format':'21.01'}
    r=requests.post(url+'/api/tools', headers=headers, json=payload, timeout=60)
    print(name, r.status_code)
    try:
        data=r.json()
    except Exception:
        print(r.text[:500])
        continue
    print(json.dumps({'jobs':[j.get('id') for j in data.get('jobs',[])], 'outputs':[(o.get('name'), o.get('id')) for o in data.get('outputs',[])]}, indent=2))
PY"

